[{"order":1,"type":"heading","text":"Creating Custom CLI Commands in Flask"},{"order":2,"type":"paragraph","text":"Flask relies on Click for its command line interface. This integration allows developers to easily extend the 'flask' command with their own custom operations, such as database initialization, data seeding, or maintenance tasks."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"Before creating custom commands, ensure you have Flask installed in your Python environment. Flask version 2.0 and higher comes with built-in support for Click-based CLI commands out of the box."},{"order":5,"type":"subheading","text":"Writing Your First Custom Command"},{"order":6,"type":"paragraph","text":"To add a command to the flask CLI, you use the 'app.cli.command()' decorator. The function name becomes the command name by default."},{"order":7,"type":"code","text":"from flask import Flask

app = Flask(__name__)

@app.cli.command("init-db")
def init_db():
    """Initialize the database."""
    print("Database initialized successfully!")"},{"order":8,"type":"subheading","text":"Adding Arguments and Options"},{"order":9,"type":"paragraph","text":"Click allows you to pass arguments and options to your custom CLI commands seamlessly using decorators provided by the click library."},{"order":10,"type":"code","text":"import click

@app.cli.command("create-user")
@click.argument("username")
@click.option("--admin", is_flag=True, help="Create an admin user.")
def create_user(username, admin):
    """Create a new user in the system."""
    role = "Administrator" if admin else "Standard User"
    print(f"Creating user '{username}' with role: {role}")"},{"order":11,"type":"subheading","text":"Executing the Commands"},{"order":12,"type":"paragraph","text":"To run your newly created commands, make sure your FLASK_APP environment variable is set properly, then invoke them through your terminal."},{"order":13,"type":"code","text":"export FLASK_APP=app.py
flask init-db
flask create-user johndoe --admin"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Always include docstrings for your commands; Click uses them as the help text in the terminal."},{"order":16,"type":"bullet_point","text":"Organize large sets of commands into groups using 'app.cli.group()' to keep your codebase modular and maintainable."}]
